VALUES ('yang-xingmi', '杨行密', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庐州人，唐末起兵后任淮南节度使，与孙儒等军阀争夺江淮。控制扬州及淮南后受封吴王，为杨吴奠基；其子杨渥继位，政权由权臣徐温掌握；杨吴以淮南为根基，在五代北方政权更迭中维持江淮独立。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨行密"}]'::jsonb, NULL, '太祖', '吴太祖')
