VALUES ('liu-jun-bei', '刘钧', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '刘旻之子，954年继位，改名刘钧。北汉继续以契丹为外援，对后周、北宋用兵并数次遭败；968年去世后，养子刘继恩、刘继元相继继位；人口与财力劣势使北汉依靠契丹仍难扭转战略处境。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘钧"}]'::jsonb, '睿皇帝', NULL, '北汉睿皇帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-jiyuan', '刘继元', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '刘钧养子，继刘继恩被杀后即位。北汉在北宋持续围攻下日益困窘，979年宋太宗亲征太原，刘继元出降，北汉亡，宋完成对中原与北方主要地区的统一；北汉归降后十国割据结束，宋完成主要汉地政权统一。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘继元"}]'::jsonb, NULL, NULL, '北汉末帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhao-kuangyin', '赵匡胤', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '后周禁军将领，陈桥兵变后受禅称帝，建立北宋并逐步削弱藩镇、整合中央军权。他继续推进统一战争，先后平定荆南、湖南、后蜀及南汉，为宋初统一奠基；在位960—976年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵匡胤"}]'::jsonb, NULL, '太祖', '宋太祖')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhao-kuangyi', '赵光义', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '赵匡胤之弟，继位后继续统一战争，灭北汉，使中原与南方大部纳入宋朝统治。其北伐辽朝在高梁河受挫，随后以文官体系和中央集权巩固新王朝；在位976—997年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵光义"}]'::jsonb, NULL, '太宗', '宋太宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhao-heng', '赵恒', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '宋太宗第三子、宋真宗，继位后面对辽军南下，1004年与辽订澶渊之盟，确立宋辽长期和平与岁币关系。其朝推行文治并扩充科举，后期政治与财政议题亦渐受关注；在位997—1022年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋真宗"}]'::jsonb, NULL, '真宗', '宋真宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
