VALUES ('huang-chao', '黄巢', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['起义领袖'], '唐末起义领袖，曹州冤句人，曾以盐贩为业。乾符年间起兵反唐，转战南北并于880年攻入长安、称帝建大齐；唐军与沙陀军反攻后，起义军瓦解，黄巢在狼虎谷自杀（一说被杀）。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄巢"}]'::jsonb, NULL, NULL, NULL)
