VALUES ('wang-wei', '王维', ARRAY[]::text[], NULL, NULL, 701, 1, NULL, 'year', 761, 1, NULL, 'year', ARRAY['诗人','画家'], '唐代诗人、画家，字摩诘，河东蒲州人。早年入仕，安史之乱时曾受伪职，乱平后复职；诗歌多写山水田园，兼擅绘画与音乐，与孟浩然并称“王孟”。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王维"}]'::jsonb, NULL, NULL, NULL)
