VALUES ('xuanzang', '玄奘', ARRAY[]::text[], NULL, NULL, 602, 1, NULL, 'year', 664, 1, NULL, 'year', ARRAY['高僧','学者'], '唐代高僧、译经家，俗姓陈，名祎，洛州缑氏人。贞观年间西行求法，历经中亚抵达印度，回国后在长安主持译经并撰《大唐西域记》，推动唯识学传播。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/玄奘"}]'::jsonb, NULL, NULL, NULL)
