VALUES ('jianzhen', '鉴真', ARRAY[]::text[], NULL, NULL, 688, 1, NULL, 'year', 763, 1, NULL, 'year', ARRAY['高僧'], '唐代律宗高僧，俗姓淳于，扬州江阳人。受日本僧人邀请，历经多次失败后于753年东渡成功，在日本传戒、建寺并传播佛教戒律与唐代文化。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鉴真"}]'::jsonb, NULL, NULL, NULL)
