VALUES ('yang-guifei', '杨玉环', ARRAY[]::text[], NULL, NULL, 719, 1, NULL, 'year', 756, 1, NULL, 'year', ARRAY['后妃'], '唐玄宗贵妃，名玉环，蒲州永乐人。原为寿王李瑁妃，后入宫受宠；安史之乱中随玄宗西行，马嵬驿兵变后被赐死，具体经过见于唐代史籍与后世文学。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨贵妃"}]'::jsonb, NULL, NULL, NULL)
