VALUES ('zhang-xun', '张巡', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 757, 1, NULL, 'year', ARRAY['军事家'], '唐代将领，字巡，南阳人。安史之乱中坚守睢阳，守城数月以阻叛军南下江淮，至德二载城破被俘遇害；守城事迹见于两《唐书》，后世对其守城中的食人记载亦有讨论。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张巡"}]'::jsonb, NULL, NULL, NULL)
