VALUES ('bao-zheng', '包拯', ARRAY[]::text[], NULL, NULL, 999, 1, NULL, 'year', 1062, 1, NULL, 'year', ARRAY['政治家'], '北宋官员，字希仁，庐州合肥人。历任监察御史、开封府尹及枢密副使，以执法严明、敢于弹劾权贵闻名；身后谥孝肃，包公形象在戏曲小说中进一步传奇化。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/包拯"}]'::jsonb, NULL, NULL, NULL)
