VALUES ('ouyang-xiu', '欧阳修', ARRAY[]::text[], NULL, NULL, 1007, 1, NULL, 'year', 1072, 1, NULL, 'year', ARRAY['文学家','政治家'], '北宋文坛领袖，唐宋八大家之一，主持庆历新政；主持编撰《新唐书》，并独撰《新五代史》，提携苏轼、曾巩等后进。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/欧阳修"}]'::jsonb, NULL, NULL, NULL)
