VALUES ('si-ma-guang', '司马光', ARRAY[]::text[], NULL, NULL, 1019, 1, NULL, 'year', 1086, 1, NULL, 'year', ARRAY['史学家','政治家'], '北宋史学家，主编资治通鉴，元祐更化代表；他与司马康等编修《资治通鉴》；任相时废除部分新法，引发政坛争论。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马光"}]'::jsonb, NULL, NULL, NULL)
