VALUES ('shen-kuo', '沈括', ARRAY[]::text[], NULL, NULL, 1031, 1, NULL, 'year', 1095, 1, NULL, 'year', ARRAY['科学家'], '北宋科学家，梦溪笔谈作者，天文历法、物理皆有建树；《梦溪笔谈》记载磁针指南、活字印刷及地貌观察，是宋代科学史重要文献。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沈括"}]'::jsonb, NULL, NULL, NULL)
