VALUES ('han-shizhong', '韩世忠', ARRAY[]::text[], NULL, NULL, 1089, 1, NULL, 'year', 1151, 1, NULL, 'year', ARRAY['军事家'], '南宋将领，字良臣，延安人。早年从军抗金，曾在黄天荡与金军交战，后长期镇守两淮；秦桧议和时他当面质问岳飞罪证，晚年退居杭州。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩世忠"}]'::jsonb, NULL, NULL, NULL)
