VALUES ('li-gang', '李纲', ARRAY[]::text[], NULL, NULL, 1083, 1, NULL, 'year', 1140, 1, NULL, 'year', ARRAY['政治家','军事家'], '北宋末宰相，力主抗金，靖康之变前后多次起用；靖康年间组织东京防务并反对割地求和，南渡后数度出任宰执。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李纲"}]'::jsonb, NULL, NULL, NULL)
