VALUES ('wen-tianxiang', '文天祥', ARRAY[]::text[], NULL, NULL, 1236, 1, NULL, 'year', 1283, 1, NULL, 'year', ARRAY['政治家'], '南宋末丞相，抗元被俘，作正气歌，就义于大都；被俘后写下《过零丁洋》等诗，拒绝忽必烈劝降，于大都就义。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/文天祥"}]'::jsonb, NULL, NULL, NULL)
