INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('shi-chaoyi', '史朝义', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 763, NULL, NULL, 'month', ARRAY['皇帝'], '史思明长子。761年弑父继位，改元显圣；唐军与回纥军收复洛阳后，他退往莫州一带。763年部将李怀仙降唐，史朝义败亡自尽，安史之乱至此平定。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/史朝义"}]'::jsonb, NULL, NULL, NULL)
