-- dynasties
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('sui', '隋', ARRAY['隋','大隋'], 'cn', 'east_asia', 581, 3, NULL, 'month', 619, 5, NULL, 'month', 6974, 7432, 'ochre', NULL, NULL, '581年杨坚受禅建隋，589年灭陈结束南北分裂；文帝时期整顿官制、律令与户籍财政，社会经济恢复。炀帝营建东都洛阳、开通沟通南北的运河并发动高句丽战争，持续征发加剧政局危机。618年杨广被杀、李渊建唐后，洛阳杨侗仍延续隋室；619年5月杨侗被废杀，隋亡。隋代制度与交通建设成为唐朝治理和南北经济联系的重要基础。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('xu', '许', ARRAY['许','宇文化及许'], 'cn', 'east_asia', 618, 9, NULL, 'month', 619, 5, NULL, 'month', 7424, 7432, 'ochre', NULL, NULL, '宇文化及杀杨浩后自立，国号许，旋为窦建德所败，619年覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('xia-dou-jiande', '夏', ARRAY['夏','窦夏','夏王窦建德政权'], 'cn', 'east_asia', 618, 11, NULL, 'month', 621, 5, NULL, 'month', 7426, 7456, 'ochre', NULL, NULL, '窦建德于618年11月在乐寿建夏称王；621年5月虎牢战败被俘，夏政权覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('zheng', '郑', ARRAY['郑','王世充郑'], 'cn', 'east_asia', 619, 1, NULL, 'month', 621, 6, NULL, 'month', 7428, 7457, 'ochre', NULL, NULL, '王世充于619年在洛阳称帝、国号郑；621年6月4日（武德四年五月丙寅）降唐，政权覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('tang', '唐', ARRAY['唐','李唐'], 'cn', 'east_asia', 618, 6, NULL, 'month', 907, 1, NULL, 'year', 7421, 10884, 'ochre', NULL, NULL, '唐（618–907）由李渊于隋末建立，定都长安，初期经太宗治理和高宗时期的扩张形成强盛帝国；690–705年武则天改国号周，唐中宗复位后恢复李唐。玄宗开元年间臻于鼎盛，安史之乱后中央权力削弱，藩镇、宦官与朝廷长期角力；黄巢起义进一步加剧晚唐危机，907年朱温迫使哀帝禅位，唐亡。唐代科举、律令制度与文学艺术发展显著，长安也是东亚及欧亚交流的重要中心。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('zhou-wu', '武周', ARRAY['周'], 'cn', 'east_asia', 690, 1, NULL, 'year', 705, 1, NULL, 'year', 8280, 8460, 'ochre', NULL, NULL, '武周是武则天于690年改唐为周后建立的王朝，定都洛阳，至705年神龙政变后唐中宗复位而终。武则天由高宗皇后、临朝太后逐步掌握政权并正式称帝；武周延续唐代官僚与制度，同时通过选官、整顿统治巩固皇权，并以佛教建构政治声望。其统治改变唐朝皇位继承与政治格局，退位后国号复唐。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('liang-hou', '后梁', ARRAY['梁'], 'cn', 'east_asia', 907, 1, NULL, 'year', 923, 1, NULL, 'year', 10884, 11076, 'ochre', NULL, 'wudai', '唐末朱温凭宣武军控制中原，907年受禅建国、定都开封。后梁延续藩镇主导的政治格局，与河东李克用、李存勖父子长期争战；朱温死后，朱友珪、朱友贞相继卷入宫变与继承冲突。923年后唐军攻入开封，后梁覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('tang-hou', '后唐', ARRAY['唐'], 'cn', 'east_asia', 923, 1, NULL, 'year', 936, 1, NULL, 'year', 11076, 11232, 'ochre', NULL, 'wudai', '李存勖于923年灭后梁、建立后唐，定都洛阳；政权由沙陀军事集团发展而来，以唐为国号。明宗李嗣源时期一度整顿吏治、恢复秩序，后唐又于925年灭前蜀。其后皇位更迭与藩镇兵变相互交织，河东节度使石敬瑭借契丹兵攻入洛阳，后唐于936年灭亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('jin-hou', '后晋', ARRAY['晋'], 'cn', 'east_asia', 936, 1, NULL, 'year', 947, 1, NULL, 'year', 11232, 11364, 'ochre', NULL, 'wudai', '石敬瑭于936年借契丹兵推翻后唐、建立后晋，定都开封。为取得契丹支持，他称契丹主为父并割让燕云十六州，后晋因此长期受制于契丹。石重贵即位后改变对契丹的臣属姿态，引发战争；契丹军于946—947年南下攻陷开封，后晋覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('han-hou', '后汉', ARRAY['汉'], 'cn', 'east_asia', 947, 1, NULL, 'year', 951, 1, NULL, 'year', 11364, 11412, 'ochre', NULL, 'wudai', '契丹灭后晋、北撤后，刘知远于947年在太原称帝，随后进入开封建立后汉。后汉以沙陀军政集团为统治核心，疆域和国祚都较短；刘承祐即位后与郭威等将领冲突，950年郭威起兵，次年建立后周，后汉结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('zhou-hou', '后周', ARRAY['周'], 'cn', 'east_asia', 951, 1, NULL, 'year', 960, 1, NULL, 'year', 11412, 11520, 'ochre', NULL, 'wudai', '郭威于951年建立后周，定都开封；继位的柴荣整顿军队与财政，削弱割据势力，并向南唐用兵、取得淮南等地，使中原政权的统一能力增强。柴荣北伐途中病逝，幼主柴宗训继位。960年赵匡胤发动陈桥兵变，后周禅代为宋，北宋继而推进统一。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('wu-shi', '吴', ARRAY['吴','杨吴','十国吴'], 'cn', 'east_asia', 902, 1, NULL, 'year', 937, 1, NULL, 'year', 10824, 11244, 'ochre', NULL, 'shiguo', '杨行密以淮南为根基，控制扬州及江淮地区，为杨吴奠定基础。杨隆演时期徐温掌握实权，919年杨氏建立吴国，927年杨溥称帝；政权名义上由杨氏世袭，实际长期受徐氏控制。937年徐知诰迫杨溥禅位，建立南唐，杨吴结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('tang-nan', '南唐', ARRAY['唐'], 'cn', 'east_asia', 937, 1, NULL, 'year', 975, 1, NULL, 'year', 11244, 11700, 'ochre', NULL, 'shiguo', '徐知诰（李昪）于937年取代杨吴，建立南唐，以金陵为都。南唐依托江淮经济与文臣治理，李璟时期一度向闽、楚扩张；但958年败于后周，割让江北地并去帝号，国势转入守成。975年北宋攻陷金陵，后主李煜出降，南唐覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('wuyue', '吴越', ARRAY['吴越','吴越国'], 'cn', 'east_asia', 907, 1, NULL, 'year', 978, 1, NULL, 'year', 10884, 11736, 'ochre', NULL, 'shiguo', '钱镠据有两浙、以杭州为中心，钱氏政权在五代时期受封吴越王，并延续至北宋初。吴越通过向历代中原王朝称臣来维持地方自治，较少卷入北方王朝争战；钱氏经营水利、海塘和区域贸易。978年钱俶纳土归宋，两浙和平并入宋朝。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('min-fujian', '闽', ARRAY['闽','闽国'], 'cn', 'east_asia', 909, 1, NULL, 'year', 945, 1, NULL, 'year', 10908, 11340, 'ochre', NULL, 'shiguo', '王潮、王审知兄弟控制福建后，由王审知建立王氏政权，以福州为中心。闽地凭山海形势发展港口贸易，并与中原王朝保持册封关系。王审知去世后，继承纷争和福州、建州对立不断削弱政权；945年南唐军攻陷建州，王延政出降，闽亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('han-nan', '南汉', ARRAY['汉'], 'cn', 'east_asia', 917, 1, NULL, 'year', 971, 1, NULL, 'year', 11004, 11652, 'ochre', NULL, 'shiguo', '刘氏政权以广州为中心，控制岭南并曾向广西及交趾方向扩展；刘龑于917年称帝，次年改国号为汉，史称南汉。广州的港口贸易和岭南地理屏障支撑其长期独立，后期宫廷权争与统治失序加重。971年北宋军攻入广州，刘鋹出降，南汉结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('shu-qian', '前蜀', ARRAY['蜀'], 'cn', 'east_asia', 907, 1, NULL, 'year', 925, 1, NULL, 'year', 10884, 11100, 'ochre', NULL, 'shiguo', '王建在唐末据有西川，以成都为中心建立前蜀，907年称帝。前蜀以四川盆地为根基，曾控制东川并扩展至汉中等地，借地势和地方资源维持独立。王建死后王衍继位，宫廷用人及边防渐趋松弛；925年后唐军入蜀，王衍出降，前蜀亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('shu-hou', '后蜀', ARRAY['蜀'], 'cn', 'east_asia', 934, 1, NULL, 'year', 965, 2, NULL, 'month', 11208, 11581, 'ochre', NULL, 'shiguo', '孟知祥在后唐内乱中控制两川，934年于成都建立后蜀。政权以四川盆地为核心，拥有相对稳定的农业和财政基础；孟昶统治前期延续地方治理，后期宫廷开支与防务问题加重。965年北宋军攻入成都，孟昶出降，后蜀覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('jingnan', '荆南', ARRAY['南平'], 'cn', 'east_asia', 924, 1, NULL, 'year', 963, 1, NULL, 'year', 11088, 11556, 'ochre', NULL, 'shiguo', '高季兴以江陵为据点建立荆南政权，后受封南平王。其辖境较小，却扼长江中游水陆交通；政权通过朝贡、贸易和在后唐、后晋及南方诸国之间周旋维持生存，虽列为十国之一，却始终未称帝。963年高继冲纳土归宋，荆南结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('chu-nan', '楚', ARRAY['楚','马楚'], 'cn', 'east_asia', 907, 1, NULL, 'year', 951, 1, NULL, 'year', 10884, 11412, 'ochre', NULL, 'shiguo', '马殷控制湖南、以潭州（长沙）为中心建立马楚，获后梁封楚王。马楚依靠农业、茶叶贸易和与中原王朝的朝贡关系维持地方政权，马希范时期疆域与财赋达到高峰。此后诸王争位引发内战，南唐乘势攻入长沙；951年马希崇出降，马楚亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('han-bei', '北汉', ARRAY['汉'], 'cn', 'east_asia', 951, 1, NULL, 'year', 979, 1, NULL, 'year', 11412, 11748, 'ochre', NULL, 'shiguo', '后汉宗室刘崇（刘旻）于951年在太原建立北汉，统治核心在今山西北部，是五代结束后仍与北宋对峙的十国之一。北汉依靠契丹援助抵御后周、北宋，但疆域狭小、资源有限，长期处于军事压力之下。979年宋太宗围攻太原，刘继元出降，北汉灭亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('song-north', '北宋', ARRAY['宋'], 'cn', 'east_asia', 960, 2, NULL, 'month', 1127, 3, NULL, 'month', 11521, 13526, 'ochre', NULL, NULL, '960年赵匡胤在陈桥兵变后建立宋朝、定都开封；太祖、太宗先后平定主要割据政权，形成中原与南方的大体统一。北宋以文官体系、科举和中央机构改革加强中央集权，农业、城市商业、手工业与印刷文化发展。朝廷长期面对辽、西夏等北方政权，1004年澶渊之盟后宋辽维持相对稳定的边境关系。王安石变法引发持续政争；联金灭辽后宋金关系迅速破裂，1127年金军攻陷开封，徽、钦二帝被俘，北宋覆亡，宋室随后在南方延续。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('song-south', '南宋', ARRAY['宋'], 'cn', 'east_asia', 1127, 6, NULL, 'month', 1279, 3, NULL, 'month', 13529, 15350, 'ochre', NULL, NULL, '1127年靖康之变后，赵构在应天府即位，宋廷南迁并定都临安，疆域以淮河以南及东南为核心，先与金长期对峙，后又面对蒙古扩张。北方人口南迁推动江南开发，临安成为政治与商业中心，手工业、城市文化和海上贸易繁盛。1276年临安陷落后，宋室在东南沿海延续抵抗，1279年崖山战败，南宋覆亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('yan-anshi', '大燕', ARRAY['大燕','燕','安史燕'], 'cn', 'east_asia', 756, 1, NULL, 'year', 763, 12, NULL, 'month', 9072, 9167, 'ochre', NULL, NULL, '安禄山于756年2月5日在洛阳称帝、国号大燕。政权由安禄山、安庆绪、史思明、史朝义先后统治；史朝义政权于763年初败亡，具体自杀日期记载有异，末端以败亡日期范围内的推定日表示。')
